const $=(selector)=>document.querySelector(selector);
const menu=$('.menu');
const nav=$('#main-nav');
function closeMenu(){menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Open menu');nav.classList.remove('open')}
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Close menu':'Open menu');nav.classList.toggle('open',open)});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeMenu();if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)&&!document.activeElement.isContentEditable){event.preventDefault();$('#faq-search').focus()}});
const questions=[...document.querySelectorAll('.faq-list details')];
$('#faq-search').addEventListener('input',event=>{const term=event.target.value.trim().toLowerCase();let found=0;questions.forEach(item=>{const match=item.textContent.toLowerCase().includes(term);item.hidden=!match;if(match)found++});$('#faq-empty').hidden=found>0});
const sections=[...document.querySelectorAll('main section[id]')];
if('IntersectionObserver' in window){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting)nav.querySelectorAll('a').forEach(link=>link.classList.toggle('active',link.hash==='#'+entry.target.id))})},{rootMargin:'-15% 0px -55% 0px'});sections.forEach(section=>observer.observe(section))}
function webUrl(value){if(typeof value!=='string'||!value)return null;try{const url=new URL(value,window.location.href);if(url.protocol!=='https:'&&url.origin!==window.location.origin)return null;return url}catch{return null}}
function element(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text)el.textContent=text;return el}
let posts=[];let filter='all';
const filters=[...document.querySelectorAll('[data-filter]')];
function renderPosts(){const list=$('#news-list');list.replaceChildren();const visible=posts.filter(post=>filter==='all'||post.type===filter);if(!visible.length){const empty=element('div','empty-state');empty.append(element('span','empty-icon','▤'),element('h3','',filter==='all'?'No announcements yet':filter==='news'?'No community news yet':'No project updates yet'),element('p','','New posts will appear here when they are published. Visit Discord for community discussions.'));list.append(empty);return}visible.forEach(post=>{const card=element('article','post');const meta=element('div','post-meta');meta.append(element('span','',post.type==='update'?'PROJECT UPDATE':'COMMUNITY NEWS'));const date=new Date(post.date);if(Number.isFinite(date.getTime())){const time=element('time','',new Intl.DateTimeFormat('en',{month:'short',day:'numeric',year:'numeric'}).format(date));time.dateTime=date.toISOString();meta.append(time)}card.append(meta,element('h3','',post.title),element('p','',post.summary));const url=webUrl(post.url);if(url){const link=element('a','','Read announcement ↗');link.href=url.href;link.target='_blank';link.rel='noopener noreferrer';card.append(link)}list.append(card)})}
filters.forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;filters.forEach(item=>{const selected=item===button;item.classList.toggle('selected',selected);item.setAttribute('aria-pressed',String(selected))});renderPosts()}));
function renderStaff(staff){if(!staff.length)return;$('#staff-count').textContent=new Intl.NumberFormat('en').format(staff.length);const grid=element('div','staff-grid');staff.forEach(person=>{const card=element('article','staff-card');const avatar=element('div','avatar',person.name.slice(0,1).toUpperCase());const imageUrl=webUrl(person.avatar);if(imageUrl){const image=element('img');image.src=imageUrl.href;image.alt='';image.loading='lazy';image.addEventListener('error',()=>{image.remove();avatar.textContent=person.name.slice(0,1).toUpperCase()},{once:true});avatar.replaceChildren(image)}const info=element('div');info.append(element('h4','',person.name),element('p','',person.role||'Community staff'));if(/^\d{17,20}$/.test(person.discordUserId||'')){const link=element('a','','Discord profile ↗');link.href='https://discord.com/users/'+person.discordUserId;link.target='_blank';link.rel='noopener noreferrer';info.append(link)}card.append(avatar,info);grid.append(card)});$('#staff-list').replaceChildren(grid)}
function prepareVideo(config){const url=webUrl(config.trailerUrl);if(!url)return;const video=$('#hero-video');const poster=webUrl(config.trailerPoster);if(poster)video.poster=poster.href;video.src=url.href;video.hidden=false;video.preload='metadata';const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');const controls=$('.video-controls');const play=$('#video-play');function updatePlay(){play.textContent=video.paused?'Play video':'Pause video';play.setAttribute('aria-label',video.paused?'Play background video':'Pause background video')}
video.addEventListener('loadeddata',()=>{$('.hero').classList.add('has-video');controls.hidden=false;updatePlay()});video.addEventListener('playing',()=>{$('.hero').classList.add('has-video');controls.hidden=false;updatePlay()});video.addEventListener('pause',updatePlay);video.addEventListener('error',()=>{video.hidden=true;controls.hidden=true;$('.hero').classList.remove('has-video')});video.autoplay=!reduced.matches;if(!reduced.matches)video.play().catch(()=>{controls.hidden=false;updatePlay()});else{video.load();controls.hidden=false;updatePlay()}
play.addEventListener('click',()=>{if(video.paused)video.play().catch(()=>{play.textContent='Video unavailable'});else video.pause()});$('#video-sound').addEventListener('click',()=>{video.muted=!video.muted;$('#video-sound').textContent=video.muted?'Sound off':'Sound on';$('#video-sound').setAttribute('aria-label',video.muted?'Unmute background video':'Mute background video');$('#video-sound').setAttribute('aria-pressed',String(!video.muted))});document.addEventListener('visibilitychange',()=>{if(document.hidden&&!video.paused){video.dataset.resume='true';video.pause()}else if(!document.hidden&&video.dataset.resume==='true'&&!reduced.matches){delete video.dataset.resume;video.play().catch(()=>{})}});reduced.addEventListener('change',event=>{if(event.matches)video.pause()});}
function discordInvite(value){const url=webUrl(value);if(!url)return null;const host=url.hostname.toLowerCase();let code;if(host==='discord.gg')code=url.pathname.split('/')[1];else if(['discord.com','www.discord.com'].includes(host)&&url.pathname.startsWith('/invite/'))code=url.pathname.split('/')[2];if(!code||!/^[a-zA-Z0-9-]+$/.test(code))return null;return {url:'https://discord.gg/'+code,code}}
async function loadDiscord(invite){document.querySelectorAll('.discord-link').forEach(link=>{link.href=invite.url;link.target='_blank';link.rel='noopener noreferrer';if(link.classList.contains('button')){link.replaceChildren(document.createTextNode('Join Discord '),element('span','','↗'))}});$('#discord-note').textContent='Join our Discord server';$('#server-status').replaceChildren(element('i'),document.createTextNode('Discord community'));try{const response=await fetch('https://discord.com/api/v10/invites/'+encodeURIComponent(invite.code)+'?with_counts=true',{signal:AbortSignal.timeout(8000)});if(!response.ok)throw Error('Invite unavailable');const data=await response.json();if(Number.isFinite(data.approximate_member_count))$('#member-count').textContent='~'+new Intl.NumberFormat('en').format(data.approximate_member_count);if(Number.isFinite(data.approximate_presence_count))$('#online-count').textContent='~'+new Intl.NumberFormat('en').format(data.approximate_presence_count);$('.stats').title='Discord member and online counts are approximate.';if(data.guild?.name)$('#server-name').textContent=data.guild.name;if(data.guild?.description)$('#server-description').textContent=data.guild.description;if(/^\d+$/.test(data.guild?.id||'')&&/^[a-zA-Z0-9_]+$/.test(data.guild?.icon||'')){$('#server-icon').style.backgroundImage='url("https://cdn.discordapp.com/icons/'+data.guild.id+'/'+data.guild.icon+'.png?size=128")';$('#server-icon').classList.add('has-icon')}$('#server-status').replaceChildren(element('i'),document.createTextNode('Discord connected'));$('#server-status').classList.add('connected');$('#discord-note').textContent='Member counts provided by Discord'}catch{$('#server-status').replaceChildren(element('i'),document.createTextNode('Join us on Discord'));$('#discord-note').textContent='Member counts currently unavailable'}}
async function init(){try{const response=await fetch('community.json',{cache:'no-cache'});if(!response.ok)throw Error('Community information unavailable');const config=await response.json();if(typeof config.name==='string'&&config.name.trim())$('#server-name').textContent=config.name;posts=(Array.isArray(config.posts)?config.posts:[]).filter(post=>post&&typeof post.title==='string'&&typeof post.summary==='string'&&['news','update'].includes(post.type)).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0));renderPosts();renderStaff((Array.isArray(config.staff)?config.staff:[]).filter(person=>person&&typeof person.name==='string'&&person.name.trim()));prepareVideo(config);const invite=discordInvite(config.discordInvite);if(invite)await loadDiscord(invite)}catch{renderPosts()}}
init();
